@* Eight distinct slots — a host that counts past eight wraps instead of inventing a colour. *@
<TmAgentBadge Agent="@Colorised(planner, 0)" ShowStatus="false" />
<TmAgentBadge Agent="@Colorised(reviewer, 1)" ShowStatus="false" />

@code {
    private readonly AgentRef planner = new("Planner", "agent-planner");
    private readonly AgentRef reviewer = new("Reviewer", "agent-reviewer");

    // AgentRef.ColorIndex is normalised into the eight-slot palette on assignment.
    private static AgentRef Colorised(AgentRef agent, int index) => agent with { ColorIndex = index };
}

@* The page owns the snapshot and the transport; the component owns its view. *@
<TmAgentGraph Snapshot="_snapshot"
              Events="_calls"
              OnGapDetected="ReloadAsync"
              @bind-SelectedNodeId="_selectedNodeId"
              Title="Reconciliation run">
    <DetailTemplate Context="node">
        <h3>@node.Label</h3>
        <p>@node.Kind · @node.Status</p>
    </DetailTemplate>
</TmAgentGraph>

@code {
    private AgentGraphSnapshot _snapshot = new();
    private IReadOnlyList<AgentGraphCall> _calls = [];
    private string? _selectedNodeId;

    private Task ReloadAsync(long missingSequence) => LoadSnapshotAsync(missingSequence);
}

var planner = new AgentGraphNode("planner", "Planner")
{
    Kind = AgentGraphNodeKind.Agent,
    Status = AgentActivityStatus.Running,
    Group = "Core",
    Agent = new AgentRef("Planner", "planner") { ColorIndex = 0 },
};

var search = new AgentGraphNode("search", "Web search")
{
    Kind = AgentGraphNodeKind.Tool,
    Status = AgentActivityStatus.Succeeded,
};

var snapshot = new AgentGraphSnapshot
{
    Sequence = 42,
    Nodes = [planner, search, new AgentGraphNode("ledger", "Ledger") { Kind = AgentGraphNodeKind.Resource }],
    Edges = [new AgentGraphEdge("e-search", "planner", "search") { CallCount = 3, IsActive = true }],
};

@* The page owns the handoff data and the transport; the surface paints it and reports intent. *@
<TmAgentHandoff Steps="_steps"
               Title="Invoice run handoffs"
