@* Mode is the host's switch: the run view reports, the editor edits. *@
<TmFallbackChain Attempts="_attempts"
                Mode="@(editing ? FallbackChainMode.Edit : FallbackChainMode.View)"
                Chain="_chain"
                ChainChanged="OnChainChanged"
                AvailableModels="_models"
                @bind-Policy="_policy" />

@code {
    private IReadOnlyList<FallbackAttempt> _attempts = [];
    private IReadOnlyList<FallbackChainEntry>? _chain;
    private IReadOnlyList<AiModelInfo> _models = [];
    private FallbackResolutionPolicy _policy = FallbackResolutionPolicy.Fallback;

    private Task OnChainChanged(IReadOnlyList<FallbackChainEntry> chain)
    {
        _chain = chain; // persist the new order
        return Task.CompletedTask;
    }
}

